import{_ as e,o as r,c as o,ag as a}from"./chunks/framework.Cp9o0o35.js";const u=JSON.parse('{"title":"What is bridge-lite","description":"","frontmatter":{},"headers":[],"relativePath":"en/introduction.md","filePath":"en/introduction.md"}'),i={name:"en/introduction.md"};function d(n,t,s,l,h,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="what-is-bridge-lite" tabindex="-1">What is bridge-lite <a class="header-anchor" href="#what-is-bridge-lite" aria-label="Permalink to &quot;What is bridge-lite&quot;">​</a></h1><p>bridge-lite is a <strong>lightweight image viewer</strong> for photographers who shoot RAW+JPG simultaneously.</p><p>In a folder of camera JPEGs, RAWs, and developed files, bridge-lite tracks which files have been developed and what ratings they carry — your current position in the workflow.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>bridge-lite does three things:</p><ul><li><strong>Browse</strong> — Scroll through large sets of photos in the thumbnail grid</li><li><strong>Evaluate</strong> — Assign 0–5 star XMP ratings from the keyboard</li><li><strong>Compare</strong> — Switch between camera JPEG, RAW, and developed variants as one shot</li></ul><p>It does not develop, retouch, or export. Those belong to Lightroom, Capture One, or whatever tool you already use.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Out of scope</th><th>Use instead</th></tr></thead><tbody><tr><td>Developing / color grading</td><td>Lightroom / Capture One / Darkroom</td></tr><tr><td>Export / resize</td><td>Your editing tool</td></tr><tr><td>Catalog management</td><td>Your editing tool</td></tr><tr><td>Cloud sharing</td><td>Out of scope</td></tr></tbody></table><h2 id="files-are-never-modified" tabindex="-1">Files are never modified <a class="header-anchor" href="#files-are-never-modified" aria-label="Permalink to &quot;Files are never modified&quot;">​</a></h2><p>Browsing, scrolling, and filtering never touch your originals — not a single byte, timestamp, or permission bit. Safe to use directly from a memory card or network drive.</p><p>Rating data is written to XMP sidecar files only. RAW files are never modified.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>OS</td><td>macOS 14 Sonoma or later</td></tr><tr><td>Chip</td><td>Apple Silicon (M1 or later)</td></tr><tr><td>Price</td><td>Free (MIT License)</td></tr></tbody></table>',14)])])}const p=e(i,[["render",d]]);export{u as __pageData,p as default};
